  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();
    try {
      final page = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'USD', page: _currentPage));

      final newItems = page.items.where((item) => item.name.toLowerCase().contains(_searchQuery) || item.symbol.toLowerCase().contains(_searchQuery)).toList();

      setState(() {
        _allCurrencies = [..._allCurrencies, ...page.items];
        _filteredCurrenciesNotifier.value = [_filteredCurrenciesNotifier.value, newItems].expand((e) => e).toList(growable: false);
        _currentPage = page.page + 1;
        _hasMore = page.hasMore;
      });
    } finally {
      if (mounted) {
        setState(() => _isLoadingMore = false);
      }
    }
  }

  /// Применяет текущий поисковый запрос к переданному списку.
  List<CurrencyModel> _applyFilter(List<CurrencyModel> items) {
    final String lowerQuery = _searchQuery.toLowerCase();
    if (lowerQuery.isEmpty) return items;
    return items.where((currency) => currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery)).toList(growable: false);
  }

  void _filterCurrencies(String query) {
    setState(() => _searchQuery = query);
    final result = _applyFilter(_allCurrencies);
    _filteredCurrenciesNotifier.value = result;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          final List<CurrencyModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
